import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

interface ReportDatePickerProps {
  value?: Date | null;
  onChange?: (value: Date | null) => void;
  locale?: string;
}

const startOfDay = (date: Date) => {
  const next = new Date(date);
  next.setHours(0, 0, 0, 0);
  return next;
};

const shiftDays = (days: number) => {
  const next = startOfDay(new Date());
  next.setDate(next.getDate() + days);
  return next;
};

const presets = [
  { value: 'today', label: 'Сегодня', offset: 0 },
  { value: 'yesterday', label: 'Вчера', offset: -1 },
  { value: 'week-ago', label: 'Неделя назад', offset: -7 },
];

export default function ReportDatePicker({ value, onChange, locale = 'ru-RU' }: ReportDatePickerProps) {
  const [internal, setInternal] = useState<Date | null>(null);
  const selected = value !== undefined ? value : internal;

  const select = (next: Date | null) => {
    if (value === undefined) setInternal(next);
    onChange?.(next);
  };

  const activePreset = presets.find(
    (preset) => selected && startOfDay(selected).getTime() === shiftDays(preset.offset).getTime(),
  )?.value;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {presets.map((preset) => (
          <JxChip
            key={preset.value}
            role="button"
            tabIndex={0}
            active={preset.value === activePreset}
            aria-pressed={preset.value === activePreset}
            onClick={() => select(shiftDays(preset.offset))}
            onKeyDown={(event) => {
              if (event.key === 'Enter' || event.key === ' ') {
                event.preventDefault();
                select(shiftDays(preset.offset));
              }
            }}
          >
            {preset.label}
          </JxChip>
        ))}
      </div>
      <JxCalendar locale={locale} value={selected} onValueChange={select} />
    </div>
  );
}

